'use client';

import { useEffect, useRef, useState } from 'react';
import type { ProctorShieldClient } from '../../core/ProctorShieldClient';

export interface IdentityVerificationProps {
  client: ProctorShieldClient;
  sessionId: string;
  /** Camera stream from the permission gate */
  cameraStream: MediaStream | null;
  brandPrimary?: string;
  onDone: (info: { image_base64: string }) => void;
}

export function IdentityVerification(props: IdentityVerificationProps) {
  const { client, sessionId, cameraStream, brandPrimary = '#0f172a', onDone } = props;
  const videoRef = useRef<HTMLVideoElement>(null);
  const [captured, setCaptured] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (videoRef.current && cameraStream) {
      videoRef.current.srcObject = cameraStream;
    }
  }, [cameraStream]);

  const capture = () => {
    const v = videoRef.current;
    if (!v?.videoWidth) return;
    const canvas = document.createElement('canvas');
    canvas.width = v.videoWidth;
    canvas.height = v.videoHeight;
    canvas.getContext('2d')?.drawImage(v, 0, 0);
    setCaptured(canvas.toDataURL('image/jpeg', 0.8));
    setErr(null);
  };

  const submit = async () => {
    if (!captured) return;
    setBusy(true);
    setErr(null);
    try {
      await client.submitIdentity(sessionId, { image_base64: captured });
      onDone({ image_base64: captured });
    } catch (e) {
      setErr((e as Error).message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <section style={{ maxWidth: 640 }}>
      <h2 style={{ marginBottom: 4 }}>Identity verification</h2>
      <p style={{ color: '#475569', fontSize: 14, marginBottom: 12 }}>
        Center your face inside the frame, look straight at the camera, then click Capture.
      </p>
      <div style={{ position: 'relative', maxWidth: 480, marginBottom: 12 }}>
        <video
          ref={videoRef}
          autoPlay
          muted
          playsInline
          style={{
            width: '100%',
            aspectRatio: '4/3',
            background: '#000',
            borderRadius: 12,
            display: captured ? 'none' : 'block',
          }}
        />
        {captured && (
          <img
            src={captured}
            alt="Captured"
            style={{ width: '100%', aspectRatio: '4/3', objectFit: 'cover', borderRadius: 12 }}
          />
        )}
      </div>
      <div style={{ display: 'flex', gap: 8 }}>
        {!captured ? (
          <button
            type="button"
            onClick={capture}
            style={{ background: brandPrimary, color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 8, cursor: 'pointer' }}
          >
            Capture photo
          </button>
        ) : (
          <>
            <button
              type="button"
              onClick={() => setCaptured(null)}
              style={{ background: '#64748b', color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 8, cursor: 'pointer' }}
            >
              Retake
            </button>
            <button
              type="button"
              disabled={busy}
              onClick={() => void submit()}
              style={{ background: brandPrimary, color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 8, cursor: 'pointer' }}
            >
              {busy ? 'Submitting…' : 'Verify & start exam'}
            </button>
          </>
        )}
      </div>
      {err && <p style={{ color: '#b91c1c', fontSize: 13, marginTop: 12 }}>{err}</p>}
    </section>
  );
}
